"""The simulated user, generated by Inspect's ``user`` role model.

``InspectSimulator`` is τ-Rec's own ``UserSimulator``: the prompt, the role
flip, request building, the retry loop and empty-reply resampling are all
inherited. Only ``_call_once``, the single provider call, is replaced with a
call to an Inspect ``Model``.
"""
from __future__ import annotations

import time
from datetime import UTC, datetime
from typing import Any

from inspect_ai.model import (
    ChatMessage,
    ChatMessageAssistant,
    ChatMessageSystem,
    ChatMessageUser,
    GenerateConfig,
    Model,
    ModelOutput,
    ModelRefusalError,
    get_model,
)
# Private Inspect API, verified against inspect_ai 0.3.290.
from inspect_ai.model._model import ModelGenerateError

from tau_rec.agents.request_settings import native_model_name, simulator_request_settings
from tau_rec.data_model.task import Task
from tau_rec.domain import MOVIES, DomainSpec
from tau_rec.harness import LEGACY, HarnessProfile, timed_call
from tau_rec.inspect_support.config import fill_unset
from tau_rec.simulator.user_simulator import UserSimulator

DEFAULT_USER_MODEL = "openai/gpt-5-mini"

_MESSAGE_TYPES: dict[str, type[ChatMessage]] = {
    "system": ChatMessageSystem,
    "user": ChatMessageUser,
    "assistant": ChatMessageAssistant,
}


def user_model() -> Model:
    """The ``user`` role model, defaulting to the native simulator model.

    The default is a separate object from the agent's model even for the same
    name (the role and model args are part of Inspect's memoization key), at
    the native simulator temperature, on Chat Completions. ``responses_api``
    applies only to the default: a role set with ``--model-role`` keeps its
    own model args.
    """
    return get_model(
        role="user",
        default=DEFAULT_USER_MODEL,
        config=GenerateConfig(temperature=1.0),
        responses_api=False,
    )


class SimulatorCallError(Exception):
    """A simulator call native would not have turned into a usable reply.

    Raised for ``stop_reason`` ``model_length`` (native litellm raises a
    context-window error) and ``content_filter`` (conservatively, in both its
    forms). The message is fixed text only, with none of the words the native
    retry loop treats as transient, so the trial errors on the first attempt.
    """


class SimulatorProviderError(Exception):
    """An Inspect provider error, re-raised with no request or model text.

    Inspect's ``ModelGenerateError`` message embeds up to 200 lines of the
    request JSON (the simulator prompt and every turn), and
    ``ModelRefusalError`` embeds the start of the completion. The native retry
    loop matches transient-error words against ``str(error)`` and writes it to
    the call log, so either would let conversation text decide retries and
    leak into the sample error. The message here keeps only the HTTP status
    (a genuine 429 or 503 still reads as transient to the native loop) or,
    when there is none, the provider exception's class name (so a genuine
    connection error still does). The provider's own message is kept on
    ``provider_message``; the original error is chained as ``__cause__``.
    """

    def __init__(
        self,
        message: str,
        *,
        status_code: int | None = None,
        provider_message: str | None = None,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.provider_message = provider_message


def _provider_error(error: ModelGenerateError) -> SimulatorProviderError:
    if error.status_code is not None:
        detail = f"status {int(error.status_code)}"
    else:
        cause = error.__cause__
        # A class name is code-defined text, never request or model text.
        detail = type(cause).__name__ if cause is not None else "no status"
    return SimulatorProviderError(
        f"user simulator provider call failed ({detail})",
        status_code=error.status_code,
        provider_message=error.provider_message,
    )


def _inspect_messages(messages: list[dict]) -> list[ChatMessage]:
    converted = []
    for message in messages:
        message_type = _MESSAGE_TYPES.get(message["role"])
        if message_type is None:
            raise ValueError("simulator request message has an unsupported role")
        converted.append(message_type(content=message["content"]))
    return converted


def _check_stop(output: ModelOutput) -> None:
    if output.stop_reason in ("model_length", "content_filter"):
        raise SimulatorCallError(
            f"user simulator call stopped (stop_reason={output.stop_reason})"
        )
    # "max_tokens" passes through, as on the native path.


def _changed_fields(filled: GenerateConfig, explicit: GenerateConfig) -> GenerateConfig:
    """Only the fields ``fill_unset`` added, so Inspect's own merge still applies.

    Inspect lets the run's operational settings (timeout, retries, ...) win
    over a role model's config; passing the role config back in full would
    reverse that.
    """
    update: dict[str, Any] = {
        name: getattr(filled, name)
        for name in GenerateConfig.model_fields
        if getattr(filled, name) != getattr(explicit, name)
    }
    return GenerateConfig().model_copy(update=update)


class InspectSimulator(UserSimulator):
    def __init__(
        self,
        model: Model,
        task: Task,
        spec: DomainSpec = MOVIES,
        harness: HarnessProfile = LEGACY,
    ) -> None:
        # str(model) is the provider-qualified name ("openai/gpt-5-mini"); it
        # is what the call log records and what the settings rules translate.
        super().__init__(str(model), task, spec=spec, harness=harness)
        self._inspect_model = model

    async def _call_once(self, kwargs: dict, attempt: int) -> str:
        """One call to the ``user`` role model; appends its call-log row.

        ``kwargs["messages"]`` is the inherited request (system prompt plus
        role flip). The settings are the native simulator's for this model,
        filling only what the role model's own config leaves unset; the run's
        ``--temperature`` etc. belong to the agent and do not apply here.
        """
        model = self._inspect_model
        explicit = model.config
        mirrored = simulator_request_settings(native_model_name(str(model)))
        config = _changed_fields(fill_unset(mirrored, explicit), explicit)

        started_at = datetime.now(UTC).isoformat(timespec="milliseconds")
        call_start = time.perf_counter()
        try:
            output = await timed_call(
                model.generate(_inspect_messages(kwargs["messages"]), config=config),
                self._harness.call_timeout_seconds,
            )
        except ModelGenerateError as error:
            raise _provider_error(error) from error
        except ModelRefusalError as error:
            # fail_on_refusal is set: same outcome as a content_filter stop.
            raise SimulatorCallError(
                "user simulator call stopped (stop_reason=content_filter, fail_on_refusal)"
            ) from error
        _check_stop(output)

        content = output.completion
        empty = not (content and content.strip())
        self._call_log.append({
            "attempt": attempt + 1,
            "status": "empty" if empty else "ok",
            "started_at": started_at,
            "latency_seconds": time.perf_counter() - call_start,
            "requested_model": self.model,
            "response_model": output.model,
            "stop_reason": output.stop_reason,
            # Inspect's own token accounting (its ModelUsage field names).
            "usage": output.usage.model_dump(exclude_none=True) if output.usage else None,
        })
        return content
